<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<section class="team-hero panel"><div><span class="eyebrow">Collaboration sécurisée</span><h2>Mon équipe</h2><p>Invitez chaque collaborateur par e-mail. Il choisit lui-même son mot de passe et ne rejoint que votre entreprise.</p></div><span class="status-badge"><?= count($members) ?> membre<?= count($members)>1?'s':'' ?></span></section>
<?php if($previewUrl):?><div class="flash info"><strong>Lien de secours :</strong> <a href="<?= $e($previewUrl) ?>"><?= $e($previewUrl) ?></a></div><?php endif?>
<div class="team-layout"><section class="panel"><div class="panel-head"><div><h3>Inviter un collaborateur</h3><p class="panel-subtitle">Le lien expire après 48 heures et ne peut être utilisé qu’une fois.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="action" value="invite"><label class="field"><span>Nom complet</span><input name="name" required maxlength="100"></label><label class="field"><span>Adresse e-mail</span><input type="email" name="email" required maxlength="120"></label><label class="field"><span>Niveau dans l’entreprise</span><select name="membership_role"><option value="Member">Membre</option><option value="Manager">Manager</option><option value="Admin">Administrateur</option></select></label><label class="field"><span>Rôle opérationnel</span><select name="operational_role"><?php foreach($roles as$value=>$label):?><option value="<?= $e($value) ?>"><?= $e($label) ?></option><?php endforeach?></select></label><div class="form-actions"><button class="button primary">Envoyer l’invitation</button></div></form></section>
<section class="panel"><div class="panel-head"><div><h3>Tous les accès : actifs, invités et suspendus</h3><p class="panel-subtitle">La suspension retire l’accès sans supprimer l’historique.</p></div></div><div class="team-list"><?php foreach($members as$m):?><article><div><strong><?= $e($m['nom']) ?></strong><span><?= $e($m['email']) ?> · <?= $e($m['role']) ?></span></div><div class="team-state"><span class="status-badge state-<?= strtolower($e($m['status'])) ?>"><?= $e($m['status']) ?></span><?php if($this->can('users.manage')&&$m['status']==='Suspendu'):?><form method="post"><input type="hidden" name="action" value="reactivate"><input type="hidden" name="membership_id" value="<?= (int)$m['membership_id'] ?>"><button class="button secondary">Réactiver</button></form><?php endif ?><?php if($this->can('users.manage')&&$m['membership_role']!=='Owner'&&$m['status']!=='Suspendu'):?><form method="post" onsubmit="return confirm('Suspendre cet accès ?')"><input type="hidden" name="action" value="suspend"><input type="hidden" name="membership_id" value="<?= (int)$m['membership_id'] ?>"><button class="button danger-soft">Suspendre</button></form><?php endif?></div></article><?php endforeach?></div></section></div>
